'use strict';

// MODULES //

var floor = require( '@stdlib/math/base/special/floor' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var abs = require( '@stdlib/math/base/special/abs' );


// VARIABLES //

var MAX = 2147483647;


// FUNCTIONS //

/**
* Bounds an indexed product in the conservative signed32 native domain.
* @private
* @param {NonNegativeInteger} n - factor
* @param {integer} s - signed stride
* @returns {boolean} eligibility
*/
function product(n, s) {
	return ((n === 0) || (abs(s) <= floor((MAX / n))));
}
/**
* Bounds actual helper loop trip and post-step intermediates.
* @private
* @param {NonNegativeInteger} n - count
* @param {integer} s - stride
* @returns {boolean} eligibility
*/
function trip(n, s) {
	if ((n <= 1)) {
		return true;
	}
	return (((n <= (MAX - 2)) && (abs(s) > 0)) && (abs(s) <= floor(((MAX - 1) / (n + 1)))));
}


// MAIN //

/**
* Chooses JavaScript before native narrowing for valid wider metadata.
* @private
* @param {integer} M - rows
* @param {integer} N - columns
* @param {integer} KL - lower bandwidth
* @param {integer} KU - upper bandwidth
* @param {Float64Array} AB - already validated view
* @param {integer} r - normalized row stride
* @param {integer} c - normalized column stride
* @param {integer} o - offset
* @param {Int32Array} PIV - already validated output
* @param {integer} sp - normalized pivot stride
* @param {integer} op - pivot offset
* @returns {boolean} eligibility
*/
function canUseNative(M, N, KL, KU, AB, r, c, o, PIV, sp, op) { // eslint-disable-line max-params
	var end;
	var ac;
	var ar;
	var kv;
	var pp;
	var d;
	var h;
	var k;
	kv = (KL + KU);
	h = (((2 * KL) + KU) + 1);
	k = min(M, N);
	end = min((k + KL), M);
	if ((((((((kv > MAX) || (h > MAX)) || ((KU + 2) > MAX)) || ((k + 1) > MAX)) || ((k + kv) > MAX)) || ((end + 1) > MAX)) || (((end + KU) + 1) > MAX))) {
		return false;
	}
	if ((((((abs(r) > MAX) || (abs(c) > MAX)) || (o > MAX)) || (abs(sp) > MAX)) || (op > MAX))) {
		return false;
	}
	if (((!product((h - 1), r) || !product((N - 1), c)) || !product((k - 1), sp))) {
		return false;
	}
	ar = ((h - 1) * r);
	ac = ((N - 1) * c);
	pp = ((k - 1) * sp);
	if (((((o + max(ar, 0)) + max(ac, 0)) > MAX) || ((op + max(pp, 0)) > MAX))) {
		return false;
	}
	if (!trip(KL, r)) {
		return false;
	}
	if (((KL > 0) && (N > 1))) {
		d = (c - r);
		if (((abs(d) > MAX) || !trip(min(N, (kv + 1)), d))) {
			return false;
		}
	}
	return true;
}


// EXPORTS //

module.exports = canUseNative;
